40	/**
41	 * Global Exception handler for REST controllers.
42	 * <p>
43	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
44	 *
45	 * @author Vitaliy Fedoriv
46	 * @author Alexander Dudkin
47	 */
48	@ControllerAdvice
49	public class ExceptionControllerAdvice {
50	
51	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
52	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
53	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
54	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
55	    private static final String ERROR_DUPLICATE_TELEPHONE = "An owner with the given telephone already exists";
56	    private static final String ERROR_DUPLICATE_EMAIL = "An owner with the given email already exists";
57	    private static final String ERROR_DUPLICATE_HOUSEHOLD = "An owner with the given last name and address already exists";
58	    private static final String ERROR_DUPLICATE_IDENTITY = "An owner with the given identity already exists";
59	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city has reached its maximum capacity of owners";
60	    private static final String ERROR_DAILY_LIMIT_REACHED = "The maximum number of owners for the day has already been reached";
61	
62	    /**
63	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
64	     * class.
65	     *
66	     * @param e     Object referring to the thrown exception.
67	     * @param status HTTP response status.
68	     * @param url URL request.
69	     */
70	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
71	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
72	        problemDetail.setType(URI.create(url.toString()));
73	        problemDetail.setTitle(e.getClass().getSimpleName());
74	        problemDetail.setDetail(detail);
75	        problemDetail.setProperty("timestamp", Instant.now());
76	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
77	        return problemDetail;
78	    }
79	
80	    /**
81	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
82	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
83	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
84	     * would catch it and report an authorization failure as a 500.
85	     *
86	     * @param e The {@link AccessDeniedException} to propagate
87	     * @throws AccessDeniedException always
88	     */
89	    @ExceptionHandler(AccessDeniedException.class)
90	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
91	        throw e;
92	    }
93	
94	    /**
95	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
96	     *
97	     * @param e The {@link Exception} to be handled
98	     * @param request {@link HttpServletRequest} object referring to the current request.
99	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
100	     */
101	    @ExceptionHandler(Exception.class)
102	    @ResponseBody
103	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
104	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
105	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
106	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
107	        return ResponseEntity.status(status).body(detail);
108	    }
109	
110	    /**
111	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
112	     * method returns a 404 Not Found status if an entity does not exist.
113	     *
114	     * @param e The {@link DataIntegrityViolationException} to be handled
115	     * @param request {@link HttpServletRequest} object referring to the current request.
116	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
117	     */
118	    @ExceptionHandler(DataIntegrityViolationException.class)
119	    @ResponseBody
120	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
121	        logger.warn("Data integrity violation at {} {}: {}",
122	            request.getMethod(),
123	            request.getRequestURI(),
124	            e.getMessage());
125	        logger.debug("Data integrity violation stacktrace", e);
126	        HttpStatus status = HttpStatus.NOT_FOUND;
127	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
128	        return ResponseEntity.status(status).body(detail);
129	    }
130	
131	    /**
132	     * Handles exception thrown by Bean Validation on controller methods parameters
133	     *
134	     * @param e The {@link MethodArgumentNotValidException} to be handled
135	     * @param request {@link HttpServletRequest} object referring to the current request.
136	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
137	     */
138	    @ExceptionHandler(MethodArgumentNotValidException.class)
139	    @ResponseBody
140	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
141	        HttpStatus status = HttpStatus.BAD_REQUEST;
142	        BindingErrorsResponse errors = new BindingErrorsResponse();
143	        BindingResult bindingResult = e.getBindingResult();
144	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
145	        if (bindingResult.hasErrors()) {
146	            errors.addAllErrors(bindingResult);
147	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
148	                .map(fieldError -> fieldError.getField())
149	                .distinct()
150	                .toList();
151	            detail.setProperty("errors", invalidFields);
152	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
153	                .map(fieldError -> {
154	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
155	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
156	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
157	                        fieldError.getField(),
158	                        defaultMessage,
159	                        rejectedValue);
160	                    return new ValidationMessageDto(message)
161	                        .putAdditionalProperty("field", fieldError.getField())
162	                        .putAdditionalProperty("rejectedValue", rejectedValue)
163	                        .putAdditionalProperty("defaultMessage", defaultMessage);
164	                })
165	                .toList();
166	            logger.debug("Validation error at {} {}: {}",
167	                request.getMethod(),
168	                request.getRequestURI(),
169	                bindingResult.getFieldErrors());
170	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
171	            return ResponseEntity.status(status).body(detail);
172	        }
173	        return ResponseEntity.status(status).body(detail);
174	    }
175	
176	    /**
177	     * Handles {@link InvalidRequestException} raised when a request payload is missing or blank in one
178	     * or more required fields. Returns a 400 Bad Request whose {@code errors} array lists the name of
179	     * each missing field.
180	     *
181	     * @param e The {@link InvalidRequestException} to be handled
182	     * @param request {@link HttpServletRequest} object referring to the current request.
183	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
184	     */
185	    @ExceptionHandler(InvalidRequestException.class)
186	    @ResponseBody
187	    public ResponseEntity<ProblemDetail> handleInvalidRequestException(InvalidRequestException e, HttpServletRequest request) {
188	        HttpStatus status = HttpStatus.BAD_REQUEST;
189	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
190	        detail.setProperty("errors", e.getErrors());
191	        return ResponseEntity.status(status).body(detail);
192	    }
193	
194	    /**
195	     * Handles {@link DuplicateTelephoneException} raised when an owner cannot be created because its
196	     * normalized telephone is already used by another owner. Returns a 409 Conflict.
197	     *
198	     * @param e The {@link DuplicateTelephoneException} to be handled
199	     * @param request {@link HttpServletRequest} object referring to the current request.
200	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
201	     */
202	    @ExceptionHandler(DuplicateTelephoneException.class)
203	    @ResponseBody
204	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
205	        HttpStatus status = HttpStatus.CONFLICT;
206	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
207	        return ResponseEntity.status(status).body(detail);
208	    }
209	
210	    /**
211	     * Handles {@link DuplicateEmailException} raised when an owner cannot be created because its
212	     * lower-cased email is already used by another owner. Returns a 409 Conflict.
213	     *
214	     * @param e The {@link DuplicateEmailException} to be handled
215	     * @param request {@link HttpServletRequest} object referring to the current request.
216	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
217	     */
218	    @ExceptionHandler(DuplicateEmailException.class)
219	    @ResponseBody
220	    public ResponseEntity<ProblemDetail> handleDuplicateEmailException(DuplicateEmailException e, HttpServletRequest request) {
221	        HttpStatus status = HttpStatus.CONFLICT;
222	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_EMAIL);
223	        return ResponseEntity.status(status).body(detail);
224	    }
