226	    /**
227	     * Handles {@link DuplicateHouseholdException} raised when an owner cannot be created because
228	     * another owner already has the same last name and address (compared case-insensitively with
229	     * collapsed whitespace) and the request did not opt in via {@code sharesHousehold}. Returns a
230	     * 409 Conflict.
231	     *
232	     * @param e The {@link DuplicateHouseholdException} to be handled
233	     * @param request {@link HttpServletRequest} object referring to the current request.
234	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
235	     */
236	    @ExceptionHandler(DuplicateHouseholdException.class)
237	    @ResponseBody
238	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
239	        HttpStatus status = HttpStatus.CONFLICT;
240	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_HOUSEHOLD);
241	        return ResponseEntity.status(status).body(detail);
242	    }
243	
244	    /**
245	     * Handles {@link DuplicateIdentityException} raised when an owner cannot be created because its
246	     * whole derived identity key (normalized telephone, email and household id) exactly matches an
247	     * existing owner's. This single check subsumes the former separate telephone, email and household
248	     * duplicate checks. Returns a 409 Conflict.
249	     *
250	     * @param e The {@link DuplicateIdentityException} to be handled
251	     * @param request {@link HttpServletRequest} object referring to the current request.
252	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
253	     */
254	    @ExceptionHandler(DuplicateIdentityException.class)
255	    @ResponseBody
256	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
257	        HttpStatus status = HttpStatus.CONFLICT;
258	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_IDENTITY);
259	        return ResponseEntity.status(status).body(detail);
260	    }
261	
262	    /**
263	     * Handles {@link CityCapacityException} raised when an owner cannot be created because its city
264	     * already contains the maximum number of owners (50). Returns a 409 Conflict.
265	     *
266	     * @param e The {@link CityCapacityException} to be handled
267	     * @param request {@link HttpServletRequest} object referring to the current request.
268	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
269	     */
270	    @ExceptionHandler(CityCapacityException.class)
271	    @ResponseBody
272	    public ResponseEntity<ProblemDetail> handleCityCapacityException(CityCapacityException e, HttpServletRequest request) {
273	        HttpStatus status = HttpStatus.CONFLICT;
274	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
275	        return ResponseEntity.status(status).body(detail);
276	    }
277	
278	    /**
279	     * Handles {@link DailyOwnerLimitException} raised when an owner cannot be created because the
280	     * maximum number of owners that may be registered on a single day (100) has already been reached
281	     * for that day (compared by {@code registrationDate}). Returns a 429 Too Many Requests.
282	     *
283	     * @param e The {@link DailyOwnerLimitException} to be handled
284	     * @param request {@link HttpServletRequest} object referring to the current request.
285	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
286	     */
287	    @ExceptionHandler(DailyOwnerLimitException.class)
288	    @ResponseBody
289	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitException(DailyOwnerLimitException e, HttpServletRequest request) {
290	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
291	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT_REACHED);
292	        return ResponseEntity.status(status).body(detail);
293	    }
